function(container, apiUrl, tables) {
  let currentUserId = 'user-001'; // 仮のユーザーID
  let breakRecords = [];

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#select-work-item');
    if (tables[3] && tables[3].records) {
      tables[3].records.forEach(item => {
        if (item.有効フラグ) {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        }
      });
    }
  }

  // 担当者名の表示
  function loadWorkerName() {
    const workerNameDisplay = container.querySelector('#display-worker-name');
    if (tables[0] && tables[0].records) {
      const currentUser = tables[0].records.find(user => user.ユーザーID === currentUserId);
      if (currentUser) {
        workerNameDisplay.textContent = currentUser.氏名;
      }
    }
  }

  // 工数計算
  function calculateWorkHours() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;

    if (!startTime || !endTime) {
      container.querySelector('#display-work-hours').textContent = '0時間 0分';
      container.querySelector('#display-total-hours').textContent = '0時間 0分';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    const end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      container.querySelector('#display-work-hours').textContent = '0時間 0分';
      container.querySelector('#display-total-hours').textContent = '0時間 0分';
      return;
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const breakMinutes = breakRecords.reduce((sum, record) => {
      if (record.中断時間) {
        return sum + record.中断時間;
      }
      return sum;
    }, 0);

    const workMinutes = Math.max(0, totalMinutes - breakMinutes);
    const workHours = Math.floor(workMinutes / 60);
    const workMins = workMinutes % 60;

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;

    container.querySelector('#display-work-hours').textContent = `${workHours}時間 ${workMins}分`;
    container.querySelector('#display-break-time').textContent = `${breakMinutes}分`;
    container.querySelector('#display-total-hours').textContent = `${totalHours}時間 ${totalMins}分`;
  }

  // 中断記録テーブルの再描画
  function renderBreakRecords() {
    const tbody = container.querySelector('#break-records-tbody');
    if (breakRecords.length === 0) {
      tbody.innerHTML = '<tr><td colspan="5" style="text-align: center; color: var(--text-muted); font-size: 12px;">中断記録はありません</td></tr>';
      return;
    }

    tbody.innerHTML = breakRecords.map((record, index) => `
      <tr data-index="${index}">
        <td>${record.中断開始日時 ? new Date(record.中断開始日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td>${record.中断終了日時 ? new Date(record.中断終了日時).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '-'}</td>
        <td>${record.中断理由区分 || '-'}</td>
        <td>${record.中断時間 ? record.中断時間 + '分' : '-'}</td>
        <td><button class="action-btn secondary delete-break-btn" data-index="${index}">削除</button></td>
      </tr>
    `).join('');
  }

  // 初期化
  loadWorkItems();
  loadWorkerName();

  // 現在日時の設定
  const now = new Date();
  container.querySelector('#input-work-date').value = now.toISOString().split('T')[0];
  container.querySelector('#input-start-time').value = now.toTimeString().slice(0, 5);

  // 時刻変更時の工数計算
  container.querySelector('#input-start-time').addEventListener('change', calculateWorkHours);
  container.querySelector('#input-end-time').addEventListener('change', calculateWorkHours);

  // 中断時間追加ボタン
  container.querySelector('#btn-add-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 中断記録削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-break-btn');
    if (deleteBtn) {
      const index = parseInt(deleteBtn.dataset.index);
      if (confirm('この中断記録を削除しますか？')) {
        breakRecords.splice(index, 1);
        renderBreakRecords();
        calculateWorkHours();
      }
    }
  });

  // 一時保存ボタン
  container.querySelector('#btn-temp-save').addEventListener('click', async () => {
    const workData = {
      作業員ID: currentUserId,
      作業日: new Date(container.querySelector('#input-work-date').value),
      作業開始時刻: container.querySelector('#input-start-time').value ? 
        new Date(`${container.querySelector('#input-work-date').value}T${container.querySelector('#input-start-time').value}`) : null,
      作業終了時刻: container.querySelector('#input-end-time').value ? 
        new Date(`${container.querySelector('#input-work-date').value}T${container.querySelector('#input-end-time').value}`) : null,
      プロジェクト名: container.querySelector('#input-project-name').value,
      作業場所: container.querySelector('#input-work-location').value,
      作業種別: container.querySelector('#select-work-type').value,
      作業内容: container.querySelector('#textarea-work-detail').value,
      進捗状況: '作業中',
      承認状態: '未承認',
      作成日時: new Date(),
      更新日時: new Date(),
      作成者ID: currentUserId
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      alert('一時保存しました');
    }
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async () => {
    const workDate = container.querySelector('#input-work-date').value;
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const projectName = container.querySelector('#input-project-name').value;
    const workLocation = container.querySelector('#input-work-location').value;
    const workType = container.querySelector('#select-work-type').value;
    const workDetail = container.querySelector('#textarea-work-detail').value;

    if (!workDate || !startTime || !projectName || !workLocation || !workType || !workDetail) {
      alert('必須項目を入力してください');
      return;
    }

    const startDateTime = new Date(`${workDate}T${startTime}`);
    const endDateTime = endTime ? new Date(`${workDate}T${endTime}`) : null;
    const workMinutes = endDateTime ? (endDateTime - startDateTime) / (1000 * 60) : 0;

    const workData = {
      作業員ID: currentUserId,
      作業日: new Date(workDate),
      作業開始時刻: startDateTime,
      作業終了時刻: endDateTime,
      作業時間: workMinutes,
      プロジェクト名: projectName,
      作業場所: workLocation,
      作業種別: workType,
      作業内容: workDetail,
      進捗状況: endDateTime ? '完了' : '作業中',
      承認状態: '未承認',
      作成日時: new Date(),
      更新日時: new Date(),
      作成者ID: currentUserId
    };

    const saved = await window.aivicApi.save(1, workData);
    if (saved) {
      // 中断記録も保存
      for (const breakRecord of breakRecords) {
        breakRecord.作業記録ID = saved.作業記録ID;
        await window.aivicApi.save(2, breakRecord);
      }

      alert('工数記録を確定しました');
      window.showScreen('scr-1778907226171');
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('入力内容を破棄して戻りますか？')) {
      window.showScreen('scr-1778907133295');
    }
  });

  // 履歴一覧ボタン
  container.querySelector('#btn-history').addEventListener('click', () => {
    window.showScreen('scr-1778907145716');
  });

  // 中断記録ボタン
  container.querySelector('#btn-break').addEventListener('click', () => {
    window.showScreen('scr-1778907238439');
  });

  // 初期描画
  renderBreakRecords();
  calculateWorkHours();
}
